import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.yo2CxoV2.js";const k=JSON.parse('{"title":"账号与权限","description":"","frontmatter":{},"headers":[],"relativePath":"guides/accounts-and-permissions.md","filePath":"guides/accounts-and-permissions.md","lastUpdated":1794337640000}'),n={name:"guides/accounts-and-permissions.md"};function r(p,s,d,h,l,o){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="账号与权限" tabindex="-1">账号与权限 <a class="header-anchor" href="#账号与权限" aria-label="Permalink to &quot;账号与权限&quot;">​</a></h1><h2 id="登录账号" tabindex="-1">登录账号 <a class="header-anchor" href="#登录账号" aria-label="Permalink to &quot;登录账号&quot;">​</a></h2><p>工作台使用 Django 原生认证与会话。登录字段来自 <code>AUTH_USER_MODEL.USERNAME_FIELD</code>，可以是用户名、邮箱或项目自己的工号字段；不要求用户模型一定存在 <code>username</code>。</p><p>账号需要启用并拥有后台访问资格。显示名称按用户模型提供的姓名、简称和登录标识取得，主键可以使用 UUID。</p><h2 id="模型与对象权限" tabindex="-1">模型与对象权限 <a class="header-anchor" href="#模型与对象权限" aria-label="Permalink to &quot;模型与对象权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>界面表现</th></tr></thead><tbody><tr><td>查看</td><td>列表与只读详情</td></tr><tr><td>新增</td><td>新增表单；没有查看权限时进入专门录入页</td></tr><tr><td>修改</td><td>编辑、允许的行内修改与相关写操作</td></tr><tr><td>删除</td><td>删除及符合权限规则的回收站操作</td></tr></tbody></table><p>菜单不是权限边界。服务端仍会检查模型、对象、关联明细及当前请求的数据范围。</p><p>多租户项目应在自己的 Admin 中限制 queryset：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_queryset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, request):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    queryset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> super</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().get_queryset(request)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> request.user.is_superuser:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> queryset</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> queryset.filter(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">workspace</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">request.user.workspace)</span></span></code></pre></div><p>其中 <code>workspace</code> 是业务自定义字段，并非插件内置租户系统。自定义对象权限和回收站查询也应保留同样的数据边界。</p><h2 id="用户管理与密码" tabindex="-1">用户管理与密码 <a class="header-anchor" href="#用户管理与密码" aria-label="Permalink to &quot;用户管理与密码&quot;">​</a></h2><p>原生 <code>UserAdmin</code> 新建表单、密码表单和 <code>AUTH_PASSWORD_VALIDATORS</code> 继续生效。用户密码显示设置状态，不回填编码密码，也不把它当作普通文本保存。</p><p>有权限的管理员可以在独立弹窗重置密码；资料草稿与密码弹窗分别处理。先重置密码再保存旧资料草稿，不会将密码覆盖回旧值。</p><p>自己的密码修改入口位于账号菜单；失败保留已输入的新密码供修正，成功后保持当前会话。停用自己的账号或移除后台资格后会返回登录页。</p><h2 id="登录验证码" tabindex="-1">登录验证码 <a class="header-anchor" href="#登录验证码" aria-label="Permalink to &quot;登录验证码&quot;">​</a></h2><p>「账号菜单 → 系统设置」可以设置整个站点的图片验证码策略。超级管理员或拥有 <code>ordloom.change_siteconfig</code> 的账号可以修改；这不是单个用户的个人偏好。</p><p>验证码绑定会话、单次消费，默认 180 秒过期。登录失败或验证码刷新后需要使用新验证码。</p><p>支持 HttpOnly CSRF Cookie、会话保存 CSRF 与自定义 Cookie 名称。自建客户端应按照<a href="./../reference/api.html">API 数据契约</a>处理返回的令牌。</p><p>业务 API 密钥等字段请使用<a href="./../components/secrets.html">业务凭据控件</a>，不要混用用户密码重置流程。</p>`,19)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
